def initialize_weights(model, config):
    """RADAR init: role-aware delta/orthogonal convs + residual BN damping.

    Spatial stride-1 convs use delta-orthogonal kernels to preserve signal paths,
    depthwise stride-1 convs start as channel-wise identities, and residual branch
    terminal BNs use a small non-zero gamma so blocks start near identity without
    fully shutting off branch gradients.
    """
    arch, num_classes, depth = config['arch'], config['num_classes'], config['depth']
    relu_gain = math.sqrt(2.0)

    for name, m in model.named_modules():
        if isinstance(m, nn.Conv2d):
            linear_path = name.endswith('conv2') or 'shortcut.0' in name
            gain = 1.0 if linear_path else relu_gain
            if m.groups == m.in_channels == m.out_channels and m.kernel_size == (3, 3) and m.stride == (1, 1):
                nn.init.dirac_(m.weight, groups=m.groups)
            elif m.groups == 1 and m.kernel_size == (3, 3) and m.stride == (1, 1) and m.in_channels > 3:
                nn.init.zeros_(m.weight)
                nn.init.orthogonal_(m.weight[:, :, 1, 1], gain=gain)
            else:
                nn.init.orthogonal_(m.weight, gain=gain)
        elif isinstance(m, nn.BatchNorm2d):
            nn.init.constant_(m.weight, 1)
            nn.init.constant_(m.bias, 0)
        elif isinstance(m, nn.Linear):
            if m.out_features == num_classes:
                nn.init.normal_(m.weight, 0, 1.0 / math.sqrt(m.in_features * num_classes))
            else:
                nn.init.orthogonal_(m.weight, gain=relu_gain)
            if m.bias is not None:
                nn.init.constant_(m.bias, 0)

    branch_gamma = depth ** -0.5
    with torch.no_grad():
        for m in model.modules():
            if isinstance(m, BasicBlock):
                m.bn2.weight.fill_(branch_gamma)
            elif isinstance(m, InvertedResidual) and m.use_res:
                for sub in reversed(m.conv):
                    if isinstance(sub, nn.BatchNorm2d):
                        sub.weight.fill_(branch_gamma)
                        break

def initialize_weights(model, config):
    """RADAR-v2: diffuse delta-orthogonal convs + path-aware residual damping."""
    num_classes = config['num_classes']
    relu_gain = math.sqrt(2.0)

    for name, m in model.named_modules():
        if isinstance(m, nn.Conv2d):
            linear_path = (
                name.endswith('conv2') or 'shortcut.0' in name or
                name.endswith('conv.3') or name.endswith('conv.6')
            )
            gain = 1.0 if linear_path else relu_gain
            if m.groups == m.in_channels == m.out_channels and m.kernel_size == (3, 3) and m.stride == (1, 1):
                nn.init.dirac_(m.weight, groups=m.groups)
            elif m.groups == 1 and m.kernel_size == (3, 3) and m.stride == (1, 1) and m.in_channels > 3:
                nn.init.kaiming_normal_(m.weight, mode='fan_out', nonlinearity='relu')
                with torch.no_grad():
                    m.weight.mul_(0.1)
                nn.init.orthogonal_(m.weight[:, :, 1, 1], gain=gain)
            else:
                nn.init.orthogonal_(m.weight, gain=gain)
        elif isinstance(m, nn.BatchNorm2d):
            nn.init.constant_(m.weight, 1)
            nn.init.constant_(m.bias, 0)
        elif isinstance(m, nn.Linear):
            if m.out_features == num_classes:
                nn.init.normal_(m.weight, 0, 1.0 / math.sqrt(m.in_features * num_classes))
            else:
                nn.init.orthogonal_(m.weight, gain=relu_gain)
            if m.bias is not None:
                nn.init.constant_(m.bias, 0)

    res_blocks = sum(1 for m in model.modules() if isinstance(m, BasicBlock))
    mobile_res = sum(1 for m in model.modules() if isinstance(m, InvertedResidual) and m.use_res)
    with torch.no_grad():
        for m in model.modules():
            if isinstance(m, BasicBlock):
                m.bn2.weight.fill_(res_blocks ** -0.5)
            elif isinstance(m, InvertedResidual) and m.use_res:
                for sub in reversed(m.conv):
                    if isinstance(sub, nn.BatchNorm2d):
                        sub.weight.fill_(0.5 * (mobile_res ** -0.5))
                        break

def initialize_weights(model, config):
    """RADAR-v3: diffuse delta-orthogonal convs with progressive residual gating."""
    num_classes = config['num_classes']
    relu_gain = math.sqrt(2.0)
    for name, m in model.named_modules():
        if isinstance(m, nn.Conv2d):
            if 'shortcut.0' in name:
                nn.init.dirac_(m.weight)
            else:
                linear_path = name.endswith('conv2') or name.endswith('conv.3') or name.endswith('conv.6')
                gain = 1.0 if linear_path else relu_gain
                if m.groups == m.in_channels == m.out_channels and m.kernel_size == (3, 3) and m.stride == (1, 1):
                    nn.init.dirac_(m.weight, groups=m.groups)
                elif m.groups == 1 and m.kernel_size == (3, 3) and m.stride == (1, 1) and m.in_channels > 3:
                    nn.init.kaiming_normal_(m.weight, mode='fan_out', nonlinearity='relu')
                    with torch.no_grad():
                        m.weight.mul_(0.08)
                    nn.init.orthogonal_(m.weight[:, :, 1, 1], gain=gain)
                else:
                    nn.init.orthogonal_(m.weight, gain=gain)
        elif isinstance(m, nn.BatchNorm2d):
            nn.init.constant_(m.weight, 1)
            nn.init.constant_(m.bias, 0)
        elif isinstance(m, nn.Linear):
            if m.out_features == num_classes:
                nn.init.normal_(m.weight, 0, 1.0 / math.sqrt(m.in_features * num_classes))
            else:
                nn.init.orthogonal_(m.weight, gain=relu_gain)
            if m.bias is not None:
                nn.init.constant_(m.bias, 0)
    res_blocks = [m for m in model.modules() if isinstance(m, BasicBlock)]
    mob_blocks = [m for m in model.modules() if isinstance(m, InvertedResidual) and m.use_res]
    with torch.no_grad():
        L = max(1, len(res_blocks))
        for i, m in enumerate(res_blocks):
            m.bn2.weight.fill_(0.1 + 0.12 * math.sqrt((i + 1) / L))
        K = max(1, len(mob_blocks))
        for m in mob_blocks:
            for sub in reversed(m.conv):
                if isinstance(sub, nn.BatchNorm2d):
                    sub.weight.fill_(0.5 * (K ** -0.5))
                    break
